/** Every component docs route, including inherited-only composition checks. */
export function materialComponentRoutes(): MaterialRoute[] {
  const routes = new Map<string, MaterialRoute>();
  for (const entry of materialCoverage) {
    if (!entry.docsRoute?.startsWith("components/")) continue;
    const path = `/${entry.docsRoute}`;
    const current = routes.get(path);
    if (!current) routes.set(path, { path, family: entry.family, roles: [...entry.roles] });
    else current.roles = [...new Set<MaterialRole>([...current.roles, ...entry.roles])];
  }
  return [...routes.values()].sort((a, b) => a.path.localeCompare(b.path));
}
